<?php if(!defined('ABSPATH')){exit;}function leb_render_db_card_statuses(array $status):void{if($status['exists']){echo'<div class="leb-db-status-row">';echo'<span class="leb-db-status-label">'.esc_html__('Table Created:','listing-engine-backend').'</span>';echo'<span class="leb-badge leb-badge--success">&#10003; '.esc_html__('Yes','listing-engine-backend').'</span>';echo'</div>';}else{echo'<div class="leb-db-status-row">';echo'<span class="leb-db-status-label">'.esc_html__('Table Created:','listing-engine-backend').'</span>';echo'<span class="leb-badge leb-badge--error">&#10007; '.esc_html__('Not Created','listing-engine-backend').'</span>';echo'</div>';}if($status['exists']){if($status['rows_complete']){echo'<div class="leb-db-status-row">';echo'<span class="leb-db-status-label">'.esc_html__('Rows Complete:','listing-engine-backend').'</span>';echo'<span class="leb-badge leb-badge--success">&#10003; '.esc_html__('All Present','listing-engine-backend').'</span>';echo'</div>';}else{echo'<div class="leb-db-status-row">';echo'<span class="leb-db-status-label">'.esc_html__('Rows Complete:','listing-engine-backend').'</span>';echo'<span class="leb-badge leb-badge--warning">&#9888; '.esc_html__('Missing Rows','listing-engine-backend').'</span>';echo'</div>';}}}